{{include reference="ReleaseNotes.Code.Change.ChangeDisplayerVelocityMacros"/}}
{{velocity}} ## Inputs: ## - $changeItems ## - $displayEditLink ## A migration note is read by someone about to upgrade, who needs to know what it is about and what to do: each note ## is displayed as its title, linking to its page, followed by its summary, and by a link to the details its page ## holds when it has a description. #foreach ($item in $changeItems) #set ($changeDoc = $xwiki.getDocument($item)) #set ($changeObject = $changeDoc.getObject("ReleaseNotes.Code.Change.ChangeClass")) #generateDisplayEditLink($displayEditLink, $changeDoc)## ## The title and the reference are emitted into a link, so both are escaped: left raw, a value carrying wiki ## syntax would close the link and have the rest of its value parsed on its own. The label of a link is parsed ## once as part of the link and once more as the content of that link, so the title is escaped twice. #set ($title = $services.rendering.escape("$!changeObject.getValue('title')", 'xwiki/2.1'))## #set ($title = $services.rendering.escape($title, 'xwiki/2.1'))## #set ($changeReference = $services.rendering.escape($services.model.serialize($changeDoc.documentReference, 'default'), 'xwiki/2.1'))## * ((( (% class="rn-migration-change" %)[[$title>>doc:$changeReference]]${displayEditLinkMarkup}
## Display the summary through the change document, so that its rich text is rendered in the context of that ## document rather than of this displayer, the way the change's own page renders it. $changeDoc.display('summary', 'view', $changeObject) #if ("$!changeObject.getValue('description')" != '')
[[${moreDetailsLabel}>>doc:$changeReference]] #end ))) #end {{/velocity}}
